    offers = []
    for i in range(1, m + 1):
        l, r = map(int, input_lines[i].split())
        offers.append((l, r))

    result = [0] * (n + 1)

    for x in range(1, n + 1):
        occupied = set()
        for l, r in offers:
            duration = r - l + 1
            if duration < x:
                continue

            overlap = False
            for day in range(l, r + 1):
                if day in occupied:
                    overlap = True
                    break

            if not overlap:
                for day in range(l, r + 1):
                    occupied.add(day)

        result[x] = len(occupied)

