def solution(input_string):
    import sys
    from collections import deque

    lines = input_string.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0 and k > 1:
            x = x // k
        return x

    def state_key(nums):
        return tuple(sorted(nums))

    def dfs(remaining, depth, visited, path):
        if depth == 0:
            return None

        state = state_key(remaining)
        if state in visited:
            return None
        visited.add(state)

        ns = len(remaining)
        if ns == 1:
            if remaining[0] == 1:
                return path[:]
            return None

        to_remove = list(range(ns))

        for i in to_remove:
            for j in to_remove:
                if i < j:
                    x, y = remaining[i], remaining[j]
                    z = f(x + y)

                    new_remaining = remaining[:i] + remaining[i+1:j] + remaining[j+1:] + [z]
                    new_remaining = sorted(new_remaining)

                    new_path = path + [(x, y)]

                    result = dfs(new_remaining, depth - 1, visited, new_path)
                    if result is not None:
                        return result

            # Pruning: if smallest number in remaining is too large, might be impossible
            # But since we have limited sum, this is a heuristic
            pass

        return None

    for depth in range(n - 1):
        visited = set()
        result = dfs(a, depth, visited, [])
        if result is not None:
            return "YES\n" + "\n".join(f"{x} {y}" for x, y in result)

    return "NO"
