import sys
from typing import List, Set, Dict
from collections import defaultdict

def get_connected_components(n: int, edges: List[tuple]) -> List[int]:
    """Find connected component sizes using Union-Find."""
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            if size[px] < size[py]:
                px, py = py, px
            parent[py] = px
            size[px] += size[py]
            return True
        return False

    for u, v in edges:
        union(u, v)

    # Collect component sizes
    components = defaultdict(int)
    for i in range(1, n + 1):
        root = find(i)
        components[root] = size[root]

    return list(components.values())

def is_lucky(num: int) -> bool:
    """Check if a number is lucky (only contains 4 and 7)."""
    return '23568901' not in str(num).lstrip('-').replace('4', '').replace('7', '')

def get_lucky_numbers(up_to_n: int) -> List[int]:
    """Generate all lucky numbers up to n."""
    lucky = []
    if n := 10**5:
        # Generate all lucky numbers using DFS
        def dfs(current, length):
            if current > n:
                return
            if current > 0:
                lucky.append(current)
            if length < 10:
                dfs(current * 10 + 4, length + 1)
                dfs(current * 10 + 7, length + 1)
        dfs(0, 0)
    else:
        for i in range(4, up_to_n + 1, 10):
            if i == 0:
                continue
            if str(i).lstrip('-').replace('4', '').replace('7', '') == '':
                lucky.append(i)
        # Better approach
        lucky = []
        queue = [4, 7]
        idx = 0
        while idx < len(queue):
            curr = queue[idx]
            if curr > up_to_n:
                continue
            lucky.append(curr)
            if curr * 10 + 4 <= up_to_n:
                queue.append(curr * 10 + 4)
            if curr * 10 + 7 <= up_to_n:
                queue.append(curr * 10 + 7)
            idx += 1
    return sorted(set(lucky))

def solution(input_str: str) -> str:
    n = int(input_str.split()[0])
    m = int(input_str.split()[1])

    edges = []
    start_idx = 2
    parts = input_str.split()
    idx = 0
    ptr = start_idx

    while idx < n * 2:
        u = int(parts[ptr])
        v = int(parts[ptr + 1])
        edges.append((u, v))
        ptr += 2
        idx += 2

    # Find connected components
    components = get_connected_components(n, edges)

    # Check if any component is already lucky
    for comp_size in components:
        if is_lucky(comp_size):
            return "0\n"

    # Get all lucky numbers up to n
    lucky = get_lucky_numbers(n)

    if not lucky:
        return "-1\n"

    # Try to form lucky numbers by merging components
    best_result = [n + 1]  # Track minimum roads needed

    # DP approach for subset sum
    min_roads = {}
    min_roads[0] = 0

    for comp_size in components:
        # Create new list to avoid modification issues
        new_roads = min_roads.copy()

        for existing_sum, roads in min_roads.items():
            new_sum = existing_sum + comp_size
            if new_sum not in lucky and new_sum >= n:
                continue

            if new_sum in min_roads:
                new_ro = roads + 1
            else:
                new_ro = 1

            if new_sum not in new_roads or new_ro < new_roads[new_sum]:
                new_roads[new_sum] = new_ro

        # Merge with old
        min_roads.update(new_roads)

    # Check which lucky numbers can be formed
    for lucky_num in lucky:
        if lucky_num in min_roads:
            roads = min_roads[lucky_num]
            if roads >= len(components) + 1:
                roads = len(components)  # Max case: merge all
            best_result[0] = min(best_result[0], roads)

    if best_result[0] > n:
        return "-1\n"

    return f"{best_result[0]}\n"

