    for i, c in enumerate(vowel_str):
        char_map[ord('a') + i] = 0 if c == 'V' else 1

    # Build rules: rules[pos1][type1] = list of (pos2, type2)
    pos_rules = [[[] for _ in range(2)] for _ in range(n)]
    for pos1, t1, pos2, t2 in rules:
        t1_type = 0 if t1 == 'V' else 1
        t2_type = 0 if t2 == 'V' else 1
        pos_rules[pos1][t1_type].append((pos2, t2_type))

    def get_types_for_char(char_idx):
        """Returns (vowel_type, consonant_type) for a character"""
        vt = char_map[char_idx % 26]
        return vt

    def validate(types_arr):
        """Check if the types array satisfies all rules"""
        for pos1 in range(n):
            t1 = types_arr[pos1]
            for (pos2, t2) in pos_rules[pos1][t1]:
                if types_arr[pos2] != t2:
                    return False
        return True

    def get_char(types_arr, pos):
        """Get the smallest character of a given type (0=V, 1=C)"""
        t = types_arr[pos]
        for c_idx in range(26):
            if char_map[c_idx] == t:
                return chr(ord('a') + c_idx)
        return None

    def is_vowel_type(char_idx):
        return char_map[char_idx % 26] == 0

    def is_consonant_type(char_idx):
        return char_map[char_idx % 26] == 1

    result = None

    def backtrack(pos, current_chars, current_types):
        nonlocal result
        if result is not None:
            return

        if pos == n:
            # Convert types to characters
            word_chars = []
            for i in range(pos):
                word_chars.append(current_chars[i])
            result = ''.join(word_chars)
            return

        # Try characters from ord('a') onwards
        for char_code in range(97, ord('a') + 26):
            char = chr(char_code)
            char_type = is_vowel_type(char_code - ord('a'))

            # Check rules: if any position depends on this position having a certain type
            constraint_ok = True
            for (other_pos, other_type) in pos_rules[pos-1][1 - char_type]:
                if other_pos == pos:
                    constraint_ok = False
                    break

            if not constraint_ok:
                continue

            # Check if this type assignment is consistent with all rules
            if not constraint_ok:
                continue

            # Check if previous positions' rules allow this type
            for prev_pos in range(pos):
                if prev_pos >= n:
                    break
                t_prev = current_types[prev_pos]
                for (target_pos, target_type) in pos_rules[prev_pos][t_prev]:
                    if target_pos == pos:
                        if char_type != target_type:
                            constraint_ok = False
                            break
                if not constraint_ok:
                    break

            if not constraint_ok:
                continue

            current_chars.append(char)
            current_types.append(char_type)

            if result is None or (pos > 0 and current_chars[pos-1] < s[pos-1]):
                backtrack(pos + 1, current_chars, current_types)

            if result is None:
                current_chars.pop()
                current_types.pop()

    if not backtrack(0, [], []):
        print("-1")
