    lines = input_str.strip().split('\n')
    ts, tf, t = map(int, lines[0].split())
    n = int(lines[1])
    visitors = list(map(int, lines[2].split()))

    if n == 0:
        # No visitors, arrive at the beginning of service window
        return str(max(0, ts))

    best_arrival = None
    best_wait = None

    # Check arrival before any visitors (at or before first visitor's arrival)
    # This means Vasya arrives at time 'arrival' where 0 <= arrival <= visitors[0]
    for arrival in range(max(0, ts - (ts - visitors[0])), visitors[0] + 1):
        if arrival >= tf:
            break

        # If Vasya arrives at 'arrival' time
        # If before ts, Vasya waits until ts
        if arrival < ts:
            current_time = ts
            wait = ts - arrival
        else:
            current_time = arrival
            wait = 0

        # If Vasya is the first to be served, finish at current_time + t
        finish = current_time + t
        if finish < tf:
            if best_wait is None or wait < best_wait:
                best_wait = wait
                best_arrival = arrival
        else:
            if best_wait is None or wait < best_wait:
                best_wait = wait
                best_arrival = arrival

        # Also check arriving just before the first visitor to avoid queue
        if arrival < visitors[0] and arrival >= 0 and arrival < ts:
            finish = ts + t
            if finish < tf:
                wait_time = ts - arrival
                if best_wait is None or wait_time < best_wait:
                    best_wait = wait_time
                    best_arrival = arrival

    # Check arrival just before each existing visitor (to queue before them)
    for i in range(n):
        visit_arrival = visitors[i]
        if visit_arrival >= tf:
            break

        arrival = visit_arrival - 1
        if arrival < 0 or arrival >= tf:
            continue

        # Compute when Vasya would be served if arriving at this time
        current_time = ts
        count = 0

        # Process visitors arriving before Vasya (i.e., visitors before index i)
        for j in range(i):
            v_arr = visitors[j]
            start = max(current_time, v_arr)
            if start >= tf:
                break
            current_time = start + t

        # Now Vasya is served
        vasya_start = max(current_time, arrival)
        if vasya_start >= tf:
            continue

        vasya_finish = vasya_start + t
        if vasya_finish >= tf:
            continue

        wait = vasya_start - arrival
        if best_wait is None or wait < best_wait:
            best_wait = wait
            best_arrival = arrival

    # If we haven't found a valid solution yet, try ts itself
    if best_arrival is None:
        current_time = ts
        wait = 0
        finish = current_time + t
        if finish < tf:
            best_wait = wait
            best_arrival = ts

    if best_arrival is not None:
        return str(best_arrival)
    else:
        # Fallback: return 0
        return "0"


