    for i in range(2, int(MAX_N**0.5) + 1):
        if min_prime[i] == i:
            for j in range(i*i, MAX_N, i):
                if min_prime[j] == j:
                    min_prime[j] = i

    input_data = input_str.strip().split()
    q = int(input_data[0])
    results = []

    for i in range(q):
        r = int(input_data[1 + 2 * i])
        n = int(input_data[2 + 2 * i])

        if n == 1:
            results.append("1")
            continue

        k = 0
        temp_n = n
        while temp_n > 1:
            p = min_prime[temp_n]
            while temp_n % p == 0:
                temp_n //= p
            k += 1

        if r == 0:
            ans = pow(2, k, mod)
        else:
            ans = pow(2, k * (r + 1), mod)

        results.append(str(ans))

    return '\n'.join(results)
