        self.pos = 0

    def parse(self):
        return self.parse_expr()

    def parse_expr(self):
        # Expression = Term ('+' Term)*
        result = self.parse_term()
        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            term = self.parse_term()
            result = self.combine(result, term)
        return result

    def parse_term(self):
        if self.pos >= len(self.s):
            return 0

        if self.s[self.pos].isdigit():
            num1 = self.read_number()
            if self.pos < len(self.s) and self.s[self.pos] == '-':
                self.pos += 1
                if self.pos >= len(self.s):
                    return 0
                num2 = self.read_number()
                return self.range_concat(num1, num2)
            return num1

        if self.s[self.pos] == '(':
            self.pos += 1  # skip '('
            inner = self.parse_expr()
            if self.pos < len(self.s) and self.s[self.pos] == ')':
                self.pos += 1  # skip ')'
            return inner % MOD

        return 0

    def read_number(self):
        start_pos = self.pos
        while self.pos < len(self.s) and self.s[self.pos].isdigit():
            self.pos += 1
        return int(self.s[start_pos:self.pos]) % (10**9 + 8)

    def range_concat(self, l, r):
        """Concatenate all integers from l to r"""
        MOD = 10**9 + 7

        if l > r:
            return 0

        start, end = l, r

        while start <= end:
            first = start
            last = min(end, (10 ** (len(str(start)))) - 1)

            if first <= last:
                result = concat_same_len(first, last, len(str(first)))
                return result

            start = last + 1

        return 0

    def combine(self, a, b):
